class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        if not digits:
            return []
        phone = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl", "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
        res = []
        def backtrack(i, cur):
            if i == len(digits):
                res.append("".join(cur))
                return
            for c in phone[digits[i]]:
                cur.append(c)
                backtrack(i + 1, cur)
                cur.pop()
        backtrack(0, [])
        return res

reference_solution.javascript:
function letterCombinations(digits) {
    if (!digits) return [];
    const phone = { "2": "abc", "3": "def", "4": "ghi", "5": "jkl", "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz" };
    const res = [];
    function backtrack(i, cur) {
        if (i === digits.length) {
            res.push(cur.join(""));
            return;
        }
        for (const c of phone[digits[i]]) {
            cur.push(c);
            backtrack(i + 1, cur);
            cur.pop();
        }
    }
    backtrack(0, []);
    return res;
}
